const unitImages={},unitMeshes={},unitNames={soldier:'보병',cavalry:'기병',archer:'궁병'};
function prepareMeshes(raw){return raw.map(fs=>fs.map(([v,c])=>{const n=cross(sub(v[1],v[0]),sub(v[2],v[0])),len=Math.hypot(...n),light=.65+.35*Math.abs(dot(n,[-.4,-.5,.76])/(len||1));return{v,center:[0,1,2].map(i=>v.reduce((s,p)=>s+p[i],0)/v.length),color:'rgb('+[1,3,5].map(i=>Math.round(parseInt(c.slice(i,i+2),16)*light)).join(',')+')'}}))}
for(const name of ['cavalry','archer']){const im=new Image();im.onload=()=>{unitImages[name]=im;dirty=true};im.onerror=()=>{if(unit===name){$('#status').hidden=false;$('#status').textContent='이미지를 불러오지 못했습니다.'}};im.src=`units/${name}.webp?v=motion9`;fetch(`units/${name}.json?v=motion9`).then(r=>{if(!r.ok)throw Error();return r.json()}).then(raw=>{unitMeshes[name]=prepareMeshes(raw);if(unit===name){frames=unitMeshes[name];$('#status').hidden=true;dirty=true}}).catch(()=>{if(unit===name){$('#status').hidden=false;$('#status').textContent='3D 모델을 불러오지 못했습니다.'}})}
$('#unit').onchange=e=>{unit=e.target.value;frame=0;frames=unit==='soldier'?soldierFrames:(unitMeshes[unit]||[]);spriteDir='SW';preset('SW');$('#camera').value='SW';$('#overview').checked=false;$('#compare').checked=false;$('#mode').querySelector('[value="sprite"]').disabled=unit!=='soldier';if(unit!=='soldier'&&viewMode==='sprite'){viewMode='retouched';$('#mode').value=viewMode}names[1]=unit==='cavalry'?'달리기':'걷기';names[4]=unit==='soldier'?'주저앉기':'탈진';[...$('#actions').children].forEach((b,i)=>b.textContent=names[i]);last=performance.now();syncSprites()};
const previousMode=$('#mode').onchange;$('#mode').onchange=e=>{if(unit!=='soldier'){spriteDir='SW';$('#camera').value='SW'}previousMode(e)};
$('#camera').value='SW';preset('SW');syncSprites();
